#include "conv_transposed_2d_square_input_square_kernel_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
static const uint32_t BLOCK_DIM = 8;
static const uint32_t DEFAULT_TILE_HW = 32;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvTransposed2dSquareInputSquareKernelCustomTilingData tiling;

    const gert::Shape &xShape = context->GetInputShape(0)->GetOriginShape();
    const gert::Shape &wShape = context->GetInputShape(1)->GetOriginShape();
    // x: [N, Cin, H, W]
    // weight: [Cin, Cout, K, K] (PyTorch ConvTranspose2d weight layout)
    uint32_t N   = static_cast<uint32_t>(xShape.GetDim(0));
    uint32_t Cin = static_cast<uint32_t>(xShape.GetDim(1));
    uint32_t H   = static_cast<uint32_t>(xShape.GetDim(2));
    uint32_t W   = static_cast<uint32_t>(xShape.GetDim(3));
    uint32_t CinW= static_cast<uint32_t>(wShape.GetDim(0));
    uint32_t Cout= static_cast<uint32_t>(wShape.GetDim(1));
    uint32_t K   = static_cast<uint32_t>(wShape.GetDim(2)); // square kernel, K==wShape.GetDim(3)

    // Basic checks (optional)
    (void)CinW;

    context->SetBlockDim(BLOCK_DIM);

    uint32_t tileH = DEFAULT_TILE_HW;
    uint32_t tileW = DEFAULT_TILE_HW;
    uint32_t ocPerBlock = (Cout + BLOCK_DIM - 1) / BLOCK_DIM;

    tiling.set_N(N);
    tiling.set_Cin(Cin);
    tiling.set_Cout(Cout);
    tiling.set_H(H);
    tiling.set_W(W);
    tiling.set_K(K);
    tiling.set_tileH(tileH);
    tiling.set_tileW(tileW);
    tiling.set_ocPerBlock(ocPerBlock);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // x: [N, Cin, H, W], weight: [Cin, Cout, K, K]
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);
    gert::Shape* yShape = context->GetOutputShape(0);

    int64_t N   = xShape->GetDim(0);
    int64_t Cin = xShape->GetDim(1);
    int64_t H   = xShape->GetDim(2);
    int64_t W   = xShape->GetDim(3);
    (void)Cin;

    int64_t Cout = wShape->GetDim(1);
    int64_t K    = wShape->GetDim(2);
    // Assume stride=1, padding=0, output_padding=0, groups=1, no bias
    int64_t Hout = H + K - 1;
    int64_t Wout = W + K - 1;

    std::vector<int64_t> outShape = {N, Cout, Hout, Wout};
    yShape->SetDimNum(4);
    for (size_t i = 0; i < outShape.size(); ++i) {
        yShape->SetDim(i, outShape[i]);
    }
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

