#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor conv_transposed_2d_square_input_square_kernel_custom_impl_npu(const at::Tensor& x, const at::Tensor& weight) {
    // Infer output shape assuming stride=1, padding=0, output_padding=0
    TORCH_CHECK(x.dim() == 4, "x must be 4D [N,C,H,W]");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D [Cin,Cout,K,K]");
    int64_t N = x.size(0);
    int64_t Cin = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    TORCH_CHECK(weight.size(0) == Cin, "weight[0] must equal Cin");
    int64_t Cout = weight.size(1);
    int64_t K = weight.size(2);
    TORCH_CHECK(weight.size(3) == K, "square kernel required");
    int64_t Hout = H + K - 1;
    int64_t Wout = W + K - 1;

    at::Tensor y = at::empty({N, Cout, Hout, Wout}, x.options());

    EXEC_NPU_CMD(aclnnConvTransposed2dSquareInputSquareKernelCustom, x, weight, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_transposed_2d_square_input_square_kernel_custom", &conv_transposed_2d_square_input_square_kernel_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transposed_2d_square_input_square_kernel_custom", &conv_transposed_2d_square_input_square_kernel_custom_impl_npu, "ConvTranspose2d (square input, square kernel, stride=1, padding=0)");
}
